10	// ClassifyPII performs PII token classification on the given text and returns detected PII types
11	func (c *Classifier) ClassifyPII(text string) ([]string, error) {
12		return c.ClassifyPIIWithThreshold(text, c.Config.PIIModel.Threshold)
13	}
14	
15	// ClassifyPIIWithThreshold performs PII token classification with a custom threshold
16	func (c *Classifier) ClassifyPIIWithThreshold(text string, threshold float32) ([]string, error) {
17		if !c.IsPIIEnabled() {
18			return []string{}, fmt.Errorf("PII detection is not properly configured")
19		}
20	
21		if text == "" {
22			return []string{}, nil
23		}
24	
25		// Use ModernBERT PII token classifier for entity detection
26		tokenResult, err := c.piiInference.ClassifyTokens(text)
27		if err != nil {
28			return nil, fmt.Errorf("PII token classification error: %w", err)
29		}
30	
31		if len(tokenResult.Entities) > 0 {
32			logging.Infof("PII token classification found %d entities", len(tokenResult.Entities))
33		}
34	
35		// Extract unique PII types from detected entities
36		// Translate class_X format to named types using PII mapping
37		piiTypes := make(map[string]bool)
38		for _, entity := range tokenResult.Entities {
39			if entity.Confidence >= threshold {
40				// Translate entity type from class_X format to named type (e.g., class_6 → DATE_TIME)
41				translatedType := c.PIIMapping.TranslatePIIType(entity.EntityType)
42				piiTypes[translatedType] = true
43				logging.Infof("Detected PII entity: %s → %s ('%s') at [%d-%d] with confidence %.3f",
44					entity.EntityType, translatedType, entity.Text, entity.Start, entity.End, entity.Confidence)
45			}
46		}
47	
48		// Convert to slice
49		var result []string
50		for piiType := range piiTypes {
51			result = append(result, piiType)
52		}
53	
54		if len(result) > 0 {
55			logging.Infof("Detected PII types: %v", result)
56		}
57	
58		return result, nil
59	}
60	
61	// ClassifyPIIWithDetails performs PII token classification and returns full entity details including confidence scores
62	func (c *Classifier) ClassifyPIIWithDetails(text string) ([]PIIDetection, error) {
63		return c.ClassifyPIIWithDetailsAndThreshold(text, c.Config.PIIModel.Threshold)
64	}
65	
66	// ClassifyPIIWithDetailsAndThreshold performs PII token classification with a custom threshold and returns full entity details
67	func (c *Classifier) ClassifyPIIWithDetailsAndThreshold(text string, threshold float32) ([]PIIDetection, error) {
68		if !c.IsPIIEnabled() {
69			return []PIIDetection{}, fmt.Errorf("PII detection is not properly configured")
70		}
71	
72		if text == "" {
73			return []PIIDetection{}, nil
74		}
75	
76		// Use PII token classifier for entity detection
77		tokenResult, err := c.piiInference.ClassifyTokens(text)
78		if err != nil {
79			return nil, fmt.Errorf("PII token classification error: %w", err)
80		}
81	
82		if len(tokenResult.Entities) > 0 {
83			logging.Infof("PII token classification found %d entities", len(tokenResult.Entities))
84		}
85	
86		// Convert token entities to PII detections, filtering by threshold
87		// Translate class_X format to named types using PII mapping
88		var detections []PIIDetection
89		for _, entity := range tokenResult.Entities {
90			if entity.Confidence >= threshold {
91				// Translate entity type from class_X format to named type (e.g., class_6 → DATE_TIME)
92				translatedType := c.PIIMapping.TranslatePIIType(entity.EntityType)
93				detection := PIIDetection{
94					EntityType: translatedType,
95					Start:      entity.Start,
96					End:        entity.End,
97					Text:       entity.Text,
98					Confidence: entity.Confidence,
99				}
100				detections = append(detections, detection)
101				logging.Infof("Detected PII entity: %s → %s ('%s') at [%d-%d] with confidence %.3f",
102					entity.EntityType, translatedType, entity.Text, entity.Start, entity.End, entity.Confidence)
103			}
104		}
105	
106		if len(detections) > 0 {
107			// Log unique PII types for compatibility with existing logs
108			uniqueTypes := make(map[string]bool)
109			for _, d := range detections {
110				uniqueTypes[d.EntityType] = true
111			}
112			types := make([]string, 0, len(uniqueTypes))
113			for t := range uniqueTypes {
114				types = append(types, t)
115			}
116			logging.Infof("Detected PII types: %v", types)
117		}
118	
119		return detections, nil
120	}
121	
122	// DetectPIIInContent performs PII classification on all provided content
123	func (c *Classifier) DetectPIIInContent(allContent []string) []string {
124		var detectedPII []string
125		seenPII := make(map[string]bool)
126	
127		for _, content := range allContent {
128			if content == "" {
129				continue
130			}
131			// TODO: classifier may not handle the entire content, so we need to split the content into smaller chunks
132			piiTypes, err := c.ClassifyPII(content)
133			if err != nil {
134				logging.Errorf("PII classification error: %v", err)
135				// Continue without PII enforcement on error
136				continue
137			}
138			// Add all detected PII types, avoiding duplicates
139			for _, piiType := range piiTypes {
140				if seenPII[piiType] {
141					continue
142				}
143				detectedPII = append(detectedPII, piiType)
144				seenPII[piiType] = true
145				logging.Infof("Detected PII type '%s' in content", piiType)
146			}
147		}
148	
149		return detectedPII
150	}
151	
152	// AnalyzeContentForPII performs detailed PII analysis on multiple content pieces
153	func (c *Classifier) AnalyzeContentForPII(contentList []string) (bool, []PIIAnalysisResult, error) {
154		return c.AnalyzeContentForPIIWithThreshold(contentList, c.Config.PIIModel.Threshold)
155	}
156	
157	// AnalyzeContentForPIIWithThreshold performs detailed PII analysis with a custom threshold
158	func (c *Classifier) AnalyzeContentForPIIWithThreshold(contentList []string, threshold float32) (bool, []PIIAnalysisResult, error) {
159		if !c.IsPIIEnabled() {
160			return false, nil, fmt.Errorf("PII detection is not properly configured")
161		}
162	
163		var analysisResults []PIIAnalysisResult
164		hasPII := false
165		failedCount := 0
166		var lastErr error
167	
168		for i, content := range contentList {
169			if content == "" {
170				continue
171			}
172	
173			var result PIIAnalysisResult
174			result.Content = content
175			result.ContentIndex = i
176	
177			// Use ModernBERT PII token classifier for detailed analysis
178			tokenResult, err := c.piiInference.ClassifyTokens(content)
179			if err != nil {
180				logging.Errorf("Error analyzing content %d: %v", i, err)
181				failedCount++
182				lastErr = err
183				continue
184			}
185	
186			// Convert token entities to PII detections
187			for _, entity := range tokenResult.Entities {
188				if entity.Confidence >= threshold {
189					detection := PIIDetection{
190						EntityType: entity.EntityType,
191						Start:      entity.Start,
192						End:        entity.End,
193						Text:       entity.Text,
194						Confidence: entity.Confidence,
195					}
196					result.Entities = append(result.Entities, detection)
197					result.HasPII = true
198					hasPII = true
199				}
200			}
201	
202			analysisResults = append(analysisResults, result)
203		}
204	
205		// Fail closed: individual inference failures are tolerated as long as some
206		// content was actually classified, but if nothing could be classified the
207		// caller must not receive a benign "no PII" verdict it cannot distinguish
208		// from a clean scan.
209		if failedCount > 0 && len(analysisResults) == 0 {
210			return false, nil, fmt.Errorf("PII classification failed for all %d content item(s): %w", failedCount, lastErr)
211		}
212	
213		return hasPII, analysisResults, nil
214	}
215	
216	// collectPIIRuleContents builds the list of text contents to analyze for a PII rule.
217	func collectPIIRuleContents(piiText string, nonUserMessages []string, includeHistory bool) []string {
218		var contents []string
219		if piiText != "" {
220			contents = append(contents, piiText)
221		}
222		if includeHistory {
223			for _, msg := range nonUserMessages {
224				if msg != "" {
225					contents = append(contents, msg)
226				}
227			}
228		}
229		return contents
230	}
231	
232	// collectPIIEntityTypes extracts entity types from cached PII results that meet the threshold.
233	func (c *Classifier) collectPIIEntityTypes(ruleContents []string, ruleName string, threshold float32, piiCache map[string][]cachedPIIResult) map[string]bool {
234		entityTypes := make(map[string]bool)
235		for _, content := range ruleContents {
236			cachedResults, ok := piiCache[content]
237			if !ok {
238				continue
239			}
240			for _, cached := range cachedResults {
241				if cached.err != nil {
242					logging.Errorf("[Signal Computation] PII rule %q: inference error: %v", ruleName, cached.err)
243					continue
244				}
245				for _, entity := range cached.result.Entities {
246					if entity.Confidence >= threshold {
247						entityTypes[c.PIIMapping.TranslatePIIType(entity.EntityType)] = true
248					}
249				}
250			}
251		}
252		return entityTypes
253	}
254	
255	// findDeniedEntities returns entity types not covered by the allow-list.
256	func findDeniedEntities(entityTypes map[string]bool, allowedTypes []string) []string {
257		allowSet := make(map[string]bool, len(allowedTypes))
258		for _, allowed := range allowedTypes {
259			allowSet[strings.ToUpper(allowed)] = true
260		}
261		var denied []string
262		for entityType := range entityTypes {
263			if !allowSet[strings.ToUpper(entityType)] {
264				denied = append(denied, entityType)
265			}
266		}
267		return denied
268	}
