1	package classification
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"strconv"
8	)
9	
10	// CategoryMapping holds the mapping between indices and domain categories
11	type CategoryMapping struct {
12		CategoryToIdx         map[string]int    `json:"category_to_idx"`
13		IdxToCategory         map[string]string `json:"idx_to_category"`
14		CategorySystemPrompts map[string]string `json:"category_system_prompts,omitempty"` // Optional per-category system prompts from MCP server
15		CategoryDescriptions  map[string]string `json:"category_descriptions,omitempty"`   // Optional category descriptions
16	}
17	
18	// PIIMapping holds the mapping between indices and PII types
19	type PIIMapping struct {
20		LabelToIdx map[string]int    `json:"label_to_idx"`
21		IdxToLabel map[string]string `json:"idx_to_label"`
22	}
23	
24	// JailbreakMapping holds the mapping between indices and jailbreak types
25	// Supports both naming conventions: label_to_idx/idx_to_label and label_to_id/id_to_label
26	type JailbreakMapping struct {
27		LabelToIdx map[string]int    `json:"label_to_idx"`
28		IdxToLabel map[string]string `json:"idx_to_label"`
29		// Alternative naming (for HuggingFace compatibility)
30		LabelToID map[string]int    `json:"label_to_id"`
31		IDToLabel map[string]string `json:"id_to_label"`
32	}
33	
34	// LoadCategoryMapping loads the category mapping from a JSON file
35	func LoadCategoryMapping(path string) (*CategoryMapping, error) {
36		// Read the mapping file
37		data, err := os.ReadFile(path)
38		if err != nil {
39			return nil, fmt.Errorf("failed to read mapping file: %w", err)
40		}
41	
42		// Parse the JSON data
43		var mapping CategoryMapping
44		if err := json.Unmarshal(data, &mapping); err != nil {
45			return nil, fmt.Errorf("failed to parse mapping JSON: %w", err)
46		}
47	
48		return &mapping, nil
49	}
50	
51	// LoadPIIMapping loads the PII mapping from a JSON file
52	func LoadPIIMapping(path string) (*PIIMapping, error) {
53		// Read the mapping file
54		data, err := os.ReadFile(path)
55		if err != nil {
56			return nil, fmt.Errorf("failed to read PII mapping file: %w", err)
57		}
58	
59		// Parse the JSON data
60		var mapping PIIMapping
61		if err := json.Unmarshal(data, &mapping); err != nil {
62			return nil, fmt.Errorf("failed to parse PII mapping JSON: %w", err)
63		}
64	
65		return &mapping, nil
66	}
67	
68	// LoadJailbreakMapping loads the jailbreak mapping from a JSON file
69	// Supports both label_to_idx/idx_to_label and label_to_id/id_to_label formats
70	func LoadJailbreakMapping(path string) (*JailbreakMapping, error) {
71		// Read the mapping file
72		data, err := os.ReadFile(path)
73		if err != nil {
74			return nil, fmt.Errorf("failed to read jailbreak mapping file: %w", err)
75		}
76	
77		// Parse the JSON data - will populate whichever fields match
78		var mapping JailbreakMapping
79		if err := json.Unmarshal(data, &mapping); err != nil {
80			return nil, fmt.Errorf("failed to parse jailbreak mapping JSON: %w", err)
81		}
82	
83		// If standard fields are empty but alternative fields are populated,
84		// copy from alternative fields to standard fields for internal use
85		if len(mapping.LabelToIdx) == 0 && len(mapping.LabelToID) > 0 {
86			mapping.LabelToIdx = mapping.LabelToID
87		}
88		if len(mapping.IdxToLabel) == 0 && len(mapping.IDToLabel) > 0 {
89			mapping.IdxToLabel = mapping.IDToLabel
90		}
91	
92		return &mapping, nil
93	}
94	
95	// GetCategoryFromIndex converts a class index to category name using the mapping
96	func (cm *CategoryMapping) GetCategoryFromIndex(classIndex int) (string, bool) {
97		categoryName, ok := cm.IdxToCategory[fmt.Sprintf("%d", classIndex)]
98		return categoryName, ok
99	}
100	
101	// GetPIITypeFromIndex converts a class index to PII type name using the mapping
102	func (pm *PIIMapping) GetPIITypeFromIndex(classIndex int) (string, bool) {
103		piiType, ok := pm.IdxToLabel[fmt.Sprintf("%d", classIndex)]
104		return piiType, ok
105	}
106	
107	// stripBIOPrefix removes the BIO sequence labeling prefix from a PII type string.
108	// For example: "B-PERSON" → "PERSON", "I-DATE_TIME" → "DATE_TIME", "PERSON" → "PERSON".
109	func stripBIOPrefix(s string) string {
110		if len(s) > 2 && s[1] == '-' {
111			switch s[0] {
112			case 'B', 'I', 'E':
113				return s[2:]
114			}
115		}
116		return s
117	}
118	
119	// TranslatePIIType translates a PII type from Rust binding format to named type.
120	// Handles formats like "class_6" → "DATE_TIME" and passes through already-named types.
121	// Also strips BIO prefixes (B-PERSON → PERSON, I-DATE_TIME → DATE_TIME).
